import os
import posixpath
import sys
import tarfile

archive, destination = sys.argv[1], sys.argv[2]
destination = os.path.abspath(destination)


def reject(message):
    raise SystemExit("unpack: rejected archive: " + message)


def inside(root, path):
    try:
        return os.path.commonpath((root, path)) == root
    except ValueError:
        return False


if os.path.islink(destination):
    reject("incoming directory is a symbolic link")

root = os.path.realpath(destination)
if root != destination:
    reject("incoming directory does not resolve to itself")

try:
    tf = tarfile.open(archive, mode="r:*")
except (OSError, tarfile.TarError) as exc:
    reject(str(exc))

with tf:
    try:
        members = tf.getmembers()
    except (OSError, tarfile.TarError, EOFError) as exc:
        reject(str(exc))

    names = {}
    symlinks = set()

    for member in members:
        name = member.name
        if not name or name.startswith("/"):
            reject("absolute or empty member path %r" % name)

        components = name.split("/")
        if ".." in components:
            reject("parent traversal in member path %r" % name)

        normalized = posixpath.normpath(name)
        if normalized in ("", ".", "..") or normalized.startswith("../"):
            reject("unsafe member path %r" % name)
        if normalized in names:
            reject("duplicate member path %r" % normalized)
        names[normalized] = member

        target_path = os.path.realpath(os.path.join(root, *normalized.split("/")))
        if not inside(root, target_path):
            reject("member resolves outside incoming: %r" % name)

        if member.issym():
            symlinks.add(normalized)
        elif not (member.isdir() or member.isreg() or member.islnk()):
            reject("unsupported special member %r" % name)

    for normalized, member in names.items():
        parts = normalized.split("/")
        for index in range(1, len(parts)):
            if "/".join(parts[:index]) in symlinks:
                reject("member is nested below an archive symlink: %r" % member.name)

        if member.issym() or member.islnk():
            linkname = member.linkname
            if not linkname or linkname.startswith("/"):
                reject("unsafe link target on %r" % member.name)
            if member.issym():
                target = posixpath.normpath(
                    posixpath.join(posixpath.dirname(normalized), linkname)
                )
            else:
                target = posixpath.normpath(linkname)
            if target in ("", ".", "..") or target.startswith("../"):
                reject("link escapes incoming: %r -> %r" % (member.name, linkname))

            target_path = os.path.realpath(os.path.join(root, *target.split("/")))
            if not inside(root, target_path):
                reject("link resolves outside incoming: %r -> %r" % (member.name, linkname))

            if member.islnk():
                linked = names.get(target)
                if linked is None or not linked.isreg():
                    reject("hard link does not name an archive regular file: %r" % member.name)

    # Force all regular payloads to be readable before installing any member.
    try:
        for member in members:
            if member.isreg():
                stream = tf.extractfile(member)
                if stream is None:
                    reject("cannot read payload for %r" % member.name)
                while stream.read(1024 * 1024):
                    pass
                stream.close()
    except (OSError, tarfile.TarError, EOFError) as exc:
        reject(str(exc))

try:
    with tarfile.open(archive, mode="r:*") as tf:
        tf.extractall(path=root, members=tf.getmembers(), filter="data")
except (OSError, tarfile.TarError, EOFError) as exc:
    raise SystemExit("unpack: extraction failed: " + str(exc))
